/**
 * Technology Readiness Level (TRL) assessment for Phase 0
 *
 * Built from the October 2026 TRL re-baseline (reconciliation/phase-0/trl/): 26 critical
 * technologies rated by a three-model panel on the NASA TRL scale and AD² (advancement degree
 * of difficulty), at the scale and environment Phase 0 requires. The data is generated by
 * `scripts/build-readiness-data.js` into src/lib/data/phase-0-readiness.json; nothing here
 * restates a figure by hand.
 *
 * Divergence is kept: every model's rating is in `panelRatings`, and the headline range is the
 * panel's envelope (never an average). Ratings the owner has ruled on, or that wait on a ruling,
 * carry `ownerRuling` and `rulingStatus`.
 *
 * The March 2026 assessments are in trl-assessment-legacy.ts; `LEGACY_TRL_ASSESSMENTS` records
 * what replaced or deferred each one.
 *
 * TRL Scale:
 * 1 - Basic principles observed
 * 2 - Technology concept formulated
 * 3 - Experimental proof of concept
 * 4 - Technology validated in lab
 * 5 - Technology validated in relevant environment
 * 6 - Technology demonstrated in relevant environment
 * 7 - System prototype demonstration in operational environment
 * 8 - System complete and qualified
 * 9 - System proven in operational environment
 */

import readiness from '$lib/data/phase-0-readiness.json';
import { MARCH_2026_TRL_ASSESSMENTS } from './trl-assessment-legacy';

export type RiskClass = 'project-ending' | 'architecture-change' | 'schedule-delay' | 'cost-increase';
export type PhaseNeed = '0A' | '0B' | 'phase-1';

export interface Range {
	min: number;
	max: number;
}

/** One model's rating of a technology */
export interface PanelRating {
	model: string;
	name: string;
	currentTRL: Range;
	targetTRL: number;
	ad2: number;
	yearsToTarget: Range | null;
	riskIfFail: RiskClass;
	phaseNeed: string | null;
	confidence: string | null;
	/** The first TRL exit criterion this model finds unmet */
	unmetExitCriterion: string | null;
	fallback: string | null;
}

/** An owner ruling still open, with the questions that inform it */
export interface PendingRuling {
	question: string;
	evidence: string[];
	/** Items on the gate-rulings decision sheet */
	items: string[];
}

export interface RulingStatus {
	/** Accepted decisions (D-xx), confirmed gate rulings (G-x.x) or ruling questions */
	decided?: string[];
	/** Proposed decisions used as interim positions */
	interim?: string[];
	pending?: PendingRuling[];
	/** A model disagreement nobody has raised as a question yet */
	panel?: string;
}

export interface PathStep {
	step: string;
	content: string;
	costByModel: string;
	trlReached: string;
}

export interface TRLAssessment {
	id: string;
	technology: string;
	description: string;
	/** Current TRL, lower bound of the panel envelope */
	currentTRL: number;
	/** Upper bound of the panel envelope, when it differs */
	currentTRLMax?: number;
	/** TRL needed at the decision that commits to it (KDP-0B for 0B technologies) */
	targetTRL: number;
	/** Short statement of where the evidence stands */
	evidence: string;
	/** Steps of the consolidated development path */
	experimentsNeeded: string[];
	yearsToTarget: number;
	yearsToTargetMax?: number;
	relatedQuestionIds: string[];
	relatedBOMIds: string[];
	threadId: string;
	riskIfFail: RiskClass;
	fallbackApproach?: string;

	// Re-baseline fields (October 2026). Optional so the March rows still type-check.
	/** AD² envelope across the panel (1 = straightforward, 9 = breakthrough needed) */
	ad2?: Range;
	/** When the technology is needed */
	phaseNeed?: PhaseNeed | PhaseNeed[];
	/** Required scale, environment and duration, with model attributions */
	required?: string | null;
	/** Panel agreement: agree, diverge, or ruled by the owner */
	agreement?: 'agree' | 'diverge' | 'ruled';
	panelRatings?: PanelRating[];
	/** TRL the owner ruling makes conditional on further evidence (T26) */
	conditionalTRL?: number | null;
	ownerRuling?: { source: string; decided: string; assessedObject: string | null } | null;
	rulingStatus?: RulingStatus | null;
	path?: PathStep[];
	/** March 2026 row this technology replaces (in whole or in part) */
	supersedes?: string | null;
	assessedAt?: string;
	/** Synthesis document for this technology */
	source?: string;
}

/** A March 2026 row and what became of it */
export interface LegacyTRLAssessment extends TRLAssessment {
	supersededBy: string[];
	deferredTo: string | null;
	retiredReason: string | null;
}

export const TRL_LABELS: Record<number, string> = {
	1: 'Basic principles observed',
	2: 'Technology concept formulated',
	3: 'Experimental proof of concept',
	4: 'Technology validated in lab',
	5: 'Technology validated in relevant environment',
	6: 'Technology demonstrated in relevant environment',
	7: 'System prototype in operational environment',
	8: 'System complete and qualified',
	9: 'System proven in operational environment'
};

export const RISK_LABELS: Record<string, { label: string; color: string }> = {
	'project-ending': { label: 'Project Ending', color: '#ef4444' },
	'architecture-change': { label: 'Architecture Change', color: '#f97316' },
	'schedule-delay': { label: 'Schedule Delay', color: '#f59e0b' },
	'cost-increase': { label: 'Cost Increase', color: '#eab308' }
};

export const AGREEMENT_LABELS: Record<string, string> = {
	agree: 'Panel agrees',
	diverge: 'Panel diverges',
	ruled: 'Set by owner ruling'
};

type RawTech = (typeof readiness.technologies)[number];

const fmt = (r: Range) => (r.min === r.max ? `${r.min}` : `${r.min}–${r.max}`);
/** "Claude Opus 5.5" → "Claude", "GPT-6.1 Sol" → "GPT" */
export const shortModelName = (name: string) => name.split(/[\s-]/)[0];
const short = shortModelName;

function toAssessment(t: RawTech): TRLAssessment {
	const ratings = t.ratings as PanelRating[];
	// The evidence line names the panel envelope and the first unmet exit criterion of the
	// most conservative model (lowest upper bound), so a reader sees why the rating stops there.
	const conservative = [...ratings].sort((a, b) => a.currentTRL.max - b.currentTRL.max)[0];
	const evidence =
		`Panel envelope TRL ${fmt(t.currentTRL)} (${ratings.map((r) => `${short(r.name)} ${fmt(r.currentTRL)}`).join(', ')}).` +
		(conservative?.unmetExitCriterion ? ` Not yet met (${short(conservative.name)}): ${conservative.unmetExitCriterion}` : '');
	const fallback = ratings
		.filter((r) => r.fallback)
		.map((r) => `${short(r.name)}: ${r.fallback}`)
		.join(' ');
	return {
		id: t.id,
		technology: t.technology,
		description: t.required ?? t.technology,
		currentTRL: t.currentTRL.min,
		currentTRLMax: t.currentTRL.max !== t.currentTRL.min ? t.currentTRL.max : undefined,
		targetTRL: t.targetTRL,
		evidence,
		experimentsNeeded: t.path.map((p) => p.step),
		yearsToTarget: t.yearsToTarget?.min ?? 0,
		yearsToTargetMax: t.yearsToTarget?.max,
		relatedQuestionIds: t.relatedQuestionIds,
		relatedBOMIds: t.relatedBOMIds,
		threadId: t.threadId,
		riskIfFail: t.riskIfFail as RiskClass,
		fallbackApproach: fallback || undefined,
		ad2: t.ad2,
		phaseNeed: t.phaseNeed as PhaseNeed | PhaseNeed[],
		required: t.required,
		agreement: t.agreement as TRLAssessment['agreement'],
		panelRatings: ratings,
		conditionalTRL: t.conditionalTRL,
		ownerRuling: t.ownerRuling,
		rulingStatus: t.status as RulingStatus | null,
		path: t.path,
		supersedes: t.supersedes,
		assessedAt: readiness.assessedAt,
		source: t.synthesis
	};
}

export const TRL_ASSESSMENTS: TRLAssessment[] = readiness.technologies.map(toAssessment);

/** The March 2026 rows, each with what replaced or deferred it */
export const LEGACY_TRL_ASSESSMENTS: LegacyTRLAssessment[] = MARCH_2026_TRL_ASSESSMENTS.map((a) => {
	const row = readiness.legacyRows.find((l) => l.id === a.id);
	return {
		...a,
		supersededBy: row?.supersededBy ?? [],
		deferredTo: row?.deferredTo ?? null,
		retiredReason: row?.reason ?? null
	};
});

/** Provenance of the current assessments */
export const TRL_SOURCE = {
	assessedAt: readiness.assessedAt,
	panel: readiness.panel,
	baseline: readiness.sources.baseline
};

// === Helper functions ===

/** Get all assessments for a given thread */
export function getAssessmentsByThread(threadId: string): TRLAssessment[] {
	return TRL_ASSESSMENTS.filter((a) => a.threadId === threadId);
}

/** Get assessment by ID (current technologies, or a March 2026 row by its old id) */
export function getAssessment(id: string): TRLAssessment | undefined {
	return TRL_ASSESSMENTS.find((a) => a.id === id) ?? LEGACY_TRL_ASSESSMENTS.find((a) => a.id === id);
}

/** Get assessments related to a specific research question */
export function getAssessmentsForQuestion(questionId: string): TRLAssessment[] {
	return TRL_ASSESSMENTS.filter((a) => a.relatedQuestionIds.includes(questionId));
}

/** Get assessments related to a specific BOM item */
export function getAssessmentsForBOM(bomId: string): TRLAssessment[] {
	return TRL_ASSESSMENTS.filter((a) => a.relatedBOMIds.includes(bomId));
}

/** Compute the TRL gap (how many levels need to be advanced) */
export function getTRLGap(assessment: TRLAssessment): number {
	return assessment.targetTRL - assessment.currentTRL;
}

/** Get the maximum TRL gap (using lower bound of current TRL) */
export function getMaxTRLGap(assessment: TRLAssessment): number {
	return assessment.targetTRL - assessment.currentTRL;
}

/** Technologies whose rating or risk class waits on an owner ruling */
export function getPendingRulings(assessment: TRLAssessment): PendingRuling[] {
	return assessment.rulingStatus?.pending ?? [];
}

/** Get overall TRL statistics */
export function getTRLStats() {
	const assessments = TRL_ASSESSMENTS;
	const avgGap = assessments.reduce((sum, a) => sum + getTRLGap(a), 0) / assessments.length;
	const maxGap = Math.max(...assessments.map(getTRLGap));
	const projectEnding = assessments.filter((a) => a.riskIfFail === 'project-ending').length;
	const architectureChange = assessments.filter((a) => a.riskIfFail === 'architecture-change').length;

	return {
		totalTechnologies: assessments.length,
		averageGap: Math.round(avgGap * 10) / 10,
		maxGap,
		projectEndingRisks: projectEnding,
		architectureChangeRisks: architectureChange,
		lowestTRL: Math.min(...assessments.map((a) => a.currentTRL)),
		highestTRL: Math.max(...assessments.map((a) => a.currentTRLMax ?? a.currentTRL)),
		avgYearsToTarget:
			Math.round((assessments.reduce((sum, a) => sum + a.yearsToTarget, 0) / assessments.length) * 10) / 10,
		diverging: assessments.filter((a) => a.agreement === 'diverge').length,
		ruled: assessments.filter((a) => a.agreement === 'ruled').length,
		awaitingRuling: assessments.filter((a) => (a.rulingStatus?.pending?.length ?? 0) > 0).length,
		maxAD2: Math.max(...assessments.map((a) => a.ad2?.max ?? 0)),
		byPhaseNeed: {
			'0A': assessments.filter((a) => a.phaseNeed === '0A').length,
			'0B': assessments.filter((a) => a.phaseNeed === '0B').length
		}
	};
}
